effect.shader:
// Leituras de cada lado do centro. 12 + 1 + 12 = 25, espaçadas de um quarto de
// sigma: cobre 3 sigmas, que é onde a gaussiana acaba.
const int TAPS = 12;

// A altura de referência das medidas em pixel.
const float REFERENCIA = 1080.0;

const vec3 LUMA = vec3(0.2126, 0.7152, 0.0722);

const vec2 CANTOS[4] = vec2[4](
    vec2(-1.0, -1.0), vec2(1.0, -1.0), vec2(-1.0, 1.0), vec2(1.0, 1.0)
);

/** sRGB para luz linear. Com o Linear Workflow desligado, não faz nada. */
vec3 aLinear(vec3 c) {
    if (!linearWorkflow) return c;
    return mix(c / 12.92, pow((c + 0.055) / 1.055, vec3(2.4)), step(vec3(0.04045), c));
}

/** Luz linear para sRGB. Com o Linear Workflow desligado, não faz nada. */
vec3 deLinear(vec3 c) {
    if (!linearWorkflow) return c;
    c = max(c, vec3(0.0));
    return mix(c * 12.92, 1.055 * pow(c, vec3(1.0 / 2.4)) - 0.055, step(vec3(0.0031308), c));
}

/** Cor reta e codificada -> pré-multiplicada em luz (linear, se ligado). */
vec4 emLuz(vec4 c) { return vec4(aLinear(c.rgb) * c.a, c.a); }

/** Pré-multiplicada em luz -> cor RETA e codificada, que é o que os buffers guardam. */
vec4 empacotar(vec4 pm) {
    vec3 reto = pm.a > 0.0 ? pm.rgb / pm.a : vec3(0.0);
    return vec4(deLinear(reto), pm.a);
}

/** Sigma em fração da ALTURA, para uma largura em "pixels de 1080". Largura = 2 sigmas. */
float sigmaDe(float px) { return px / REFERENCIA * 0.5; }

/**
 * O fundo na posição `uv` da camada, pré-multiplicado e em luz.
 *
 * Média de 4 leituras a +-1 pixel cheio (o alvo é 1/4): ao descer de resolução,
 * uma leitura só pularia pixels. `acTela` leva a posição da camada para o lugar
 * dela na tela, que é onde o fundo está.
 */
vec4 fundoEm(vec2 uv) {
    vec2 d = acTexelSize * 0.25;
    vec4 soma = vec4(0.0);
    for (int i = 0; i < 4; i++) {
        vec2 t = acTela(uv + CANTOS[i] * d);
        vec4 c = background == 0 ? texture(backdropImg, t) : texture(bgLayerImg, t);
        soma += emLuz(c);
    }
    return soma * 0.25;
}

/** O alfa do recorte em `uv`: o do conteúdo, vezes a cobertura da máscara. */
float alfaEm(vec2 uv) {
    vec2 d = acTexelSize * 0.25;
    float soma = 0.0;
    for (int i = 0; i < 4; i++) {
        vec2 t = uv + CANTOS[i] * d;
        float a = texture(inputImg, t).a;
        if (useMask) a *= texture(maskImg, t).a;
        soma += a;
    }
    return soma * 0.25;
}

/**
 * Um passe do desfoque gaussiano separável.
 *
 * `passe` diz de onde ler: 0 = o fundo, 1 = o buffer do fundo, 2 = o alfa, 3 = o
 * buffer do alfa. O passo entre leituras é em fração da altura e vale um quarto de
 * sigma; na horizontal ele é dividido pela proporção, para ser o mesmo tamanho.
 * Devolve pré-multiplicado em luz; quem escreve no buffer chama `empacotar`.
 */
vec4 desfocar(int passe, vec2 uv, vec2 eixo, float sigma) {
    float passoAltura = 0.25 * sigma;
    vec2 passo = vec2(passoAltura / acAspect, passoAltura) * eixo;

    vec4 soma = vec4(0.0);
    float pesos = 0.0;
    for (int i = -TAPS; i <= TAPS; i++) {
        float x = float(i) * 0.25;
        float w = exp(-0.5 * x * x);
        vec2 p = uv + passo * float(i);

        vec4 c;
        if (passe == 0) c = fundoEm(p);
        else if (passe == 1) c = emLuz(texture(bgA, p));
        else if (passe == 2) c = vec4(alfaEm(p));
        else c = texture(aA, p);

        soma += c * w;
        pesos += w;
    }
    return soma / pesos;
}

/**
 * O peso da luz direcional neste pixel: 1 onde a borda olha para a luz, 0 onde
 * olha para o lado oposto. Sem `Directional`, 1 em todo lugar.
 *
 * A normal sai do gradiente do alfa borrado (por diferenças centrais de um texel
 * do buffer), virada para FORA. É levada para a tela por `acTela` — dois pontos, o
 * pixel e um passo na direção da normal —, então a comparação com a luz é feita
 * no espaço em que a luz existe, e não no da camada.
 */
float pesoDaDirecao(vec2 uv) {
    if (!useDirection || lightSpread >= 359.0) return 1.0;

    vec2 t = 1.0 / vec2(textureSize(aB, 0));
    float gx = texture(aB, uv + vec2(t.x, 0.0)).r - texture(aB, uv - vec2(t.x, 0.0)).r;
    float gy = texture(aB, uv + vec2(0.0, t.y)).r - texture(aB, uv - vec2(0.0, t.y)).r;

    // O gradiente em pixels: du vale 1/largura e dv vale 1/altura. Com o alfa
    // decaindo para fora, a normal para fora é o gradiente com o sinal trocado.
    vec2 g = vec2(gx / (2.0 * t.x * acAspect), gy / (2.0 * t.y));
    vec2 nCamada = -g / max(length(g), 1e-6);

    float passo = 0.02;
    vec2 duv = vec2(nCamada.x / acAspect, nCamada.y) * passo;
    vec2 d = (acTela(uv + duv) - acTela(uv)) * vec2(acAspect, 1.0);
    vec2 nTela = d / max(length(d), 1e-6);

    float angulo = radians(lightAngle);
    vec2 aLuz = vec2(cos(angulo), -sin(angulo));      // o y da tela cresce para baixo

    float metade = cos(radians(clamp(lightSpread, 1.0, 360.0)) * 0.5);
    return smoothstep(metade - 0.15, metade + 0.15, dot(nTela, aLuz));
}

/**
 * Enriquece (ou lava) a cor em volta do próprio brilho: `s=1` não mexe, acima
 * afasta os canais do cinza, abaixo aproxima. É o que tira o aspecto "lavado" da
 * luz — um contorno com a cor viva do fundo pertence à cena; um contorno cinza
 * parece um halo colado por cima.
 */
vec3 saturar(vec3 c, float s) {
    return max(mix(vec3(dot(c, LUMA)), c, s), 0.0);
}

/**
 * Ombro suave no lugar do corte reto em 1. Abaixo de 0,8 a luz passa igual;
 * acima, desliza para 1 sem nunca estourar. O corte reto (`clamp`) empilhava
 * tudo que passava de 1 no branco e achatava a cor do realce — o defeito que
 * fazia a luz forte virar uma mancha leitosa. Aqui o topo rola de mansinho e a
 * cor sobrevive.
 */
vec3 ombro(vec3 c) {
    const float joelho = 0.8;
    float folga = 1.0 - joelho;                 // 0.2
    vec3 alto = joelho + folga * (1.0 - exp(-(max(c, joelho) - joelho) / folga));
    return mix(c, alto, step(vec3(joelho), c));
}

void main() {
    vec2 uv = acScreenNorm;

    if (acPass == 0) { fragColor = empacotar(desfocar(0, uv, vec2(1.0, 0.0), sigmaDe(bgBlur))); return; }
    if (acPass == 1) { fragColor = empacotar(desfocar(1, uv, vec2(0.0, 1.0), sigmaDe(bgBlur))); return; }
    if (acPass == 2) { fragColor = desfocar(2, uv, vec2(1.0, 0.0), sigmaDe(wrapWidth)); return; }
    if (acPass == 3) { fragColor = desfocar(3, uv, vec2(0.0, 1.0), sigmaDe(wrapWidth)); return; }

    // ---- Passe final, em resolução cheia ----
    vec4 fg = texture(inputImg, uv);
    float cobertura = useMask ? texture(maskImg, uv).a : 1.0;
    float alfa = fg.a * cobertura;

    // A faixa por dentro da borda. O ganho de 2 traz o pico de 0,5 para 1: ver o
    // cabeçalho.
    float alfaBorrado = texture(aB, uv).r;
    float borda = alfa * clamp((1.0 - alfaBorrado) * 2.0, 0.0, 1.0);
    float faixa = pow(borda, max(falloff, 0.05)) * pesoDaDirecao(uv);

    // A luz: o fundo borrado, já em luz e multiplicado pelo próprio alfa (o que é
    // transparente não acende nada), tingido e com o viés de luminância. O viés
    // olha a claridade PERCEBIDA, que é a codificada — 0,5 é 0,5 nos dois modos.
    vec4 fundo = texture(bgB, uv);
    vec3 luz = aLinear(fundo.rgb) * fundo.a;
    float claridade = dot(deLinear(luz), LUMA);
    luz = mix(luz, aLinear(tint.rgb) * dot(luz, LUMA), tint.a);

    float claro = smoothstep(0.15, 0.85, claridade);
    float peso = lumBias >= 0.0 ? mix(1.0, claro, lumBias) : mix(1.0, 1.0 - claro, -lumBias);
    // Enriquece a cor e rola o topo de mansinho, em vez de cortar reto em 1.
    luz = ombro(saturar(luz * peso * intensity, wrapSat));

    if (view == 1) { fragColor = vec4(deLinear(luz), faixa); return; }
    if (view == 2) { fragColor = vec4(deLinear(luz * faixa), 1.0); return; }

    // O modo: como a luz entra por cima do recorte.
    vec3 base = aLinear(fg.rgb);
    vec3 misturado;
    if (applyMode == 0) {
        misturado = 1.0 - (1.0 - base) * (1.0 - luz);                 // Screen
    } else if (applyMode == 1) {
        misturado = min(base + luz, vec3(1.0));                       // Add
    } else if (applyMode == 2) {
        misturado = luz;                                              // Normal
    } else if (applyMode == 3) {
        misturado = max(base, luz);                                   // Lighten
    } else if (applyMode == 4) {
        misturado = (1.0 - 2.0 * luz) * base * base + 2.0 * luz * base; // Soft Light
    } else {
        misturado = mix(                                              // Overlay
            2.0 * base * luz,
            1.0 - 2.0 * (1.0 - base) * (1.0 - luz),
            step(0.5, base)
        );
    }

    vec4 resultado = vec4(deLinear(mix(base, misturado, faixa)), fg.a);
    fragColor = mix(resultado, fg, mixWithOriginal);
}
